// ==UserScript==
// @name         AI 余额查询挂件
// @namespace    https://github.com/ai-balance-widget
// @version      1.0.1
// @description  Cursor / ChatGPT / Gemini 右下角余额娘：拖拽吸附、Q 弹、数字滚动；快没了会说穷光蛋
// @author       吕宏群
// @match        https://chatgpt.com/*
// @match        https://chat.openai.com/*
// @match        https://gemini.google.com/*
// @match        https://aistudio.google.com/*
// @match        https://cursor.com/*
// @match        https://www.cursor.com/*
// @connect      cursor.com
// @connect      www.cursor.com
// @connect      chatgpt.com
// @connect      chat.openai.com
// @connect      gemini.google.com
// @connect      aistudio.google.com
// @grant        GM_xmlhttpRequest
// @grant        GM.xmlHttpRequest
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM.getValue
// @grant        GM.setValue
// @run-at       document-idle
// @noframes
// ==/UserScript==

(function () {
  'use strict'
  if (window.__abwWidget) return
  window.__abwWidget = true

  var MIN_SCALE = 0.6
  var MAX_SCALE = 1.4
  var STEP = 0.1
  var CLICK_SQ = 9
  var REFRESH_MS = 60000
  var CHANGE_MS = 900
  var ANIM_MS = 700
  var FETCH_TIMEOUT_MS = 25000
  var BROKE_PCT = 8
  var SIZE_KEY = 'abw-scale'
  var PROVIDER_KEY = 'abw-provider'

  var WHALE_SRC = 'data:image/png;base64,'
  var PROVIDERS = {
    cursor: { id: 'cursor', short: 'Cursor', label: 'Cursor 额度', hair: '#3d5a80', accent: '#00c8d8' },
    chatgpt: { id: 'chatgpt', short: 'GPT', label: 'ChatGPT 额度', hair: '#0d8a6a', accent: '#10a37f' },
    google: { id: 'google', short: 'Gemini', label: 'Gemini 额度', hair: '#3b6fd8', accent: '#8ab4f8' }
  }

  var gmXhr = (typeof GM_xmlhttpRequest === 'function' && GM_xmlhttpRequest)
    || (typeof GM !== 'undefined' && GM.xmlHttpRequest)
  var gmGet = (typeof GM_getValue === 'function')
    ? function (k, d) { return Promise.resolve(GM_getValue(k, d)) }
    : (typeof GM !== 'undefined' && GM.getValue)
      ? function (k, d) { return GM.getValue(k, d) }
      : function (k, d) {
        try {
          var v = localStorage.getItem(k)
          return Promise.resolve(v == null ? d : JSON.parse(v))
        } catch (e) { return Promise.resolve(d) }
      }
  var gmSet = (typeof GM_setValue === 'function')
    ? function (k, v) { GM_setValue(k, v) }
    : (typeof GM !== 'undefined' && GM.setValue)
      ? function (k, v) { GM.setValue(k, v) }
      : function (k, v) {
        try { localStorage.setItem(k, JSON.stringify(v)) } catch (e) {}
      }

  function hostOf() {
    var h = (location.hostname || '').toLowerCase()
    if (h.indexOf('cursor.com') !== -1) return 'cursor'
    if (h.indexOf('chatgpt.com') !== -1 || h.indexOf('openai.com') !== -1) return 'chatgpt'
    if (h.indexOf('gemini.google.com') !== -1 || h.indexOf('aistudio.google.com') !== -1) return 'google'
    return 'cursor'
  }

  function whaleSrc() {
    if (WHALE_SRC.indexOf('PLACEHOLDER') === -1) return WHALE_SRC
    return 'assets/DSniang02.png'
  }

  function injectCss() {
    if (document.getElementById('abw-style')) return
    var css = [
      '.abw-root{position:fixed;right:0;bottom:0;--abw-scale:1;--abw-base:clamp(96px,calc(min(196px,min(100vw,100vh)*0.22)*var(--abw-scale)),292px);width:var(--abw-base);height:var(--abw-base);cursor:grab;touch-action:none;user-select:none;-webkit-user-select:none;z-index:2147483646;font-family:ui-sans-serif,system-ui,"Segoe UI",sans-serif;transition:left .16s ease,top .16s ease,transform .3s ease}',
      '.abw-root.abw-left{transform:scaleX(-1)}',
      '.abw-root.abw-dragging{cursor:grabbing;transition:none}',
      '.abw-body{position:absolute;left:0;top:0;width:100%;height:100%;transform-origin:50% 100%;transition:transform .22s cubic-bezier(.34,1.56,.64,1)}',
      '.abw-img{width:var(--abw-base);height:var(--abw-base);display:block;pointer-events:none;-webkit-user-drag:none;user-select:none}',
      '.abw-text{position:absolute;left:44.346%;top:25.5%;transform:translate(-50%,-50%);text-align:center;color:#536ba9;line-height:1.18;white-space:nowrap;--abw-u:calc(var(--abw-base)/1026);pointer-events:none;transition:transform .3s ease}',
      '.abw-root.abw-left .abw-text{transform:translate(-50%,-50%) scaleX(-1)}',
      '.abw-label{font-size:calc(var(--abw-u)*68);font-weight:600;letter-spacing:.06em}',
      '.abw-amount{font-size:calc(var(--abw-u)*119);font-weight:800;line-height:1.05}',
      '.abw-amount.abw-broke{color:#c45c6a;font-size:calc(var(--abw-u)*96)}',
      '.abw-hint{font-size:calc(var(--abw-u)*54);color:#9fb0d9;letter-spacing:.02em}',
      '.abw-size{position:absolute;top:4px;right:4px;display:flex;gap:4px;opacity:0;transition:opacity .15s ease;z-index:2}',
      '.abw-tabs{position:absolute;left:50%;bottom:6%;transform:translateX(-50%);display:flex;gap:4px;opacity:0;transition:opacity .15s ease;z-index:2}',
      '.abw-root.abw-left .abw-tabs{transform:translateX(-50%) scaleX(-1)}',
      '.abw-root:hover .abw-size,.abw-root:hover .abw-tabs{opacity:1}',
      '.abw-size button,.abw-tabs button{height:20px;border:none;border-radius:10px;background:rgba(83,107,169,.85);color:#fff;font-size:11px;line-height:1;padding:0 7px;cursor:pointer;display:flex;align-items:center;justify-content:center;user-select:none}',
      '.abw-size button{width:20px;padding:0;border-radius:50%;font-size:13px}',
      '.abw-tabs button.abw-on{background:#536ba9}',
      '.abw-size button:hover,.abw-tabs button:hover{background:#536ba9}'
    ].join('\n')
    var el = document.createElement('style')
    el.id = 'abw-style'
    el.textContent = css
    document.documentElement.appendChild(el)
  }

  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v) }
  function viewport() {
    return {
      w: window.innerWidth || document.documentElement.clientWidth || 1280,
      h: window.innerHeight || document.documentElement.clientHeight || 800
    }
  }
  function num(v) {
    var n = Number(v)
    return isFinite(n) ? n : null
  }
  function walk(obj, fn, depth) {
    if (!obj || typeof obj !== 'object' || depth > 8) return
    fn(obj)
    if (Array.isArray(obj)) {
      for (var i = 0; i < obj.length; i++) walk(obj[i], fn, depth + 1)
      return
    }
    var keys = Object.keys(obj)
    for (var k = 0; k < keys.length; k++) walk(obj[keys[k]], fn, depth + 1)
  }
  function pickPct(used, remaining, limit) {
    var u = num(used)
    var r = num(remaining)
    var l = num(limit)
    if (u != null && u <= 100 && (l == null || l <= 100)) return { remainingPct: clamp(100 - u, 0, 100), usedPct: u }
    if (r != null && l != null && l > 0) return { remainingPct: clamp(r / l * 100, 0, 100), remaining: r, limit: l }
    if (u != null && l != null && l > 0) return { remainingPct: clamp((l - u) / l * 100, 0, 100), remaining: l - u, limit: l }
    if (r != null && r <= 1 && r >= 0) return { remainingPct: r * 100 }
    if (r != null && r <= 100 && r >= 0 && l == null) return { remainingPct: r }
    return null
  }

  function gmRequest(opts) {
    return new Promise(function (resolve, reject) {
      var timer = setTimeout(function () { reject(new Error('timeout')) }, opts.timeout || FETCH_TIMEOUT_MS)
      function done(err, val) {
        clearTimeout(timer)
        if (err) reject(err)
        else resolve(val)
      }
      if (gmXhr) {
        gmXhr({
          method: opts.method || 'GET',
          url: opts.url,
          headers: opts.headers || {},
          data: opts.body,
          timeout: opts.timeout || FETCH_TIMEOUT_MS,
          anonymous: false,
          onload: function (res) {
            done(null, { status: res.status, text: res.responseText || '' })
          },
          onerror: function () { done(new Error('network')) },
          ontimeout: function () { done(new Error('timeout')) }
        })
        return
      }
      var ctrl = null
      try { ctrl = new AbortController() } catch (e) {}
      fetch(opts.url, {
        method: opts.method || 'GET',
        headers: opts.headers,
        body: opts.body,
        credentials: 'include',
        cache: 'no-store',
        signal: ctrl ? ctrl.signal : undefined
      }).then(function (r) {
        return r.text().then(function (t) { done(null, { status: r.status, text: t }) })
      }).catch(function () { done(new Error('network')) })
    })
  }

  function jsonReq(url, extra) {
    extra = extra || {}
    return gmRequest({
      method: extra.method || 'GET',
      url: url,
      headers: Object.assign({ Accept: 'application/json' }, extra.headers || {}),
      body: extra.body
    }).then(function (res) {
      var data = null
      try { data = JSON.parse(res.text) } catch (e) {}
      return { status: res.status, data: data, text: res.text }
    })
  }

  function fail(msg) { return { ok: false, error: msg } }

  function snapshot(amount, unit, remainingPct, hint, extra) {
    extra = extra || {}
    return {
      ok: true,
      amount: amount,
      unit: unit || '',
      remainingPct: remainingPct == null ? null : remainingPct,
      hint: hint || '点击刷新',
      broke: remainingPct != null && remainingPct <= BROKE_PCT,
      raw: extra.raw
    }
  }

  function parseCursor(data) {
    if (!data || typeof data !== 'object') return null
    var plan = data.individualUsage && data.individualUsage.plan
    if (plan) {
      if (data.isUnlimited) return snapshot(Infinity, '', 100, '不限量')
      var pct = num(plan.totalPercentUsed)
      if (pct == null) pct = num(plan.apiPercentUsed)
      var remaining = num(plan.remaining)
      var limit = num(plan.limit)
      var used = num(plan.used)
      if (remaining != null && limit != null && limit > 0) {
        var remainPct = clamp(remaining / limit * 100, 0, 100)
        if (limit >= 1000) return snapshot(remaining / 100, 'USD', remainPct, '本周期剩余')
        return snapshot(remaining, '次', remainPct, '本周期剩余')
      }
      if (pct != null) return snapshot(clamp(100 - pct, 0, 100), '%', clamp(100 - pct, 0, 100), '已用 ' + Math.round(pct) + '%')
      if (used != null && limit != null && limit > 0) {
        var left = limit - used
        return snapshot(left, limit >= 1000 ? 'USD' : '次', clamp(left / limit * 100, 0, 100), '本周期剩余')
      }
    }
    var pu = data.planUsage
    if (pu && (pu.remaining != null || pu.limit != null)) {
      var r = num(pu.remaining)
      var l = num(pu.limit)
      if (r != null && l != null && l > 0) return snapshot(r / 100, 'USD', clamp(r / l * 100, 0, 100), '本周期剩余')
      if (r != null) return snapshot(r / 100, 'USD', null, '本周期剩余')
    }
    return null
  }

  function fetchCursor() {
    return jsonReq('https://cursor.com/api/usage-summary').then(function (res) {
      if (res.status === 401 || res.status === 403) return fail('请先登录 cursor.com')
      var parsed = parseCursor(res.data)
      if (parsed) return parsed
      return jsonReq('https://cursor.com/api/dashboard/get-current-period-usage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Origin: 'https://cursor.com' },
        body: '{}'
      }).then(function (res2) {
        if (res2.status === 401 || res2.status === 403) return fail('请先登录 cursor.com')
        var p2 = parseCursor(res2.data)
        return p2 || fail('Cursor 接口结构变了')
      })
    })
  }

  function chatgptHeaders(token, accountId) {
    var h = { Authorization: 'Bearer ' + token, Accept: 'application/json' }
    if (accountId) h['ChatGPT-Account-Id'] = accountId
    return h
  }

  function parseChatQuota(data) {
    if (!data || typeof data !== 'object') return null
    var best = null
    var rl = data.rate_limit
    if (rl && typeof rl === 'object' && !Array.isArray(rl)) {
      var win = rl.primary_window || rl.five_hour || rl.five_hour_limit
      if (win && win.used_percent != null) {
        var left = clamp(100 - Number(win.used_percent), 0, 100)
        var hint = '5 小时窗口'
        if (rl.secondary_window && rl.secondary_window.used_percent != null) {
          hint = '周额度剩 ' + Math.round(100 - Number(rl.secondary_window.used_percent)) + '%'
        }
        return snapshot(left, '%', left, hint)
      }
      if (win && win.percent_left != null) {
        var pl = num(win.percent_left)
        if (pl != null) return snapshot(pl, '%', pl, '额度窗口')
      }
    }
    walk(data, function (node) {
      if (best) return
      var p = pickPct(node.used_percent || node.usedPercent || node.percent_used,
        node.remaining || node.remaining_messages || node.percent_left || node.remainingFraction,
        node.limit || node.message_cap || node.max)
      if (p && p.remainingPct != null) best = p
    }, 0)
    if (best) return snapshot(Math.round(best.remainingPct), '%', best.remainingPct, '剩余额度')
    if (data.message_cap != null) {
      var cap = num(data.message_cap)
      if (cap != null) return snapshot(cap, '条', null, '当前窗口')
    }
    return null
  }

  function fetchChatGPT() {
    return jsonReq('https://chatgpt.com/api/auth/session').then(function (ses) {
      var token = ses.data && ses.data.accessToken
      if (!token) return fail('请先登录 ChatGPT')
      var accountId = ses.data.account && (ses.data.account.id || ses.data.account.account_id)
      var h = chatgptHeaders(token, accountId)
      return jsonReq('https://chatgpt.com/backend-api/wham/usage', { headers: h }).then(function (u) {
        var parsed = parseChatQuota(u.data)
        if (parsed) return parsed
        return jsonReq('https://chatgpt.com/backend-api/conversation_limit', { headers: h }).then(function (c) {
          var p2 = parseChatQuota(c.data)
          if (p2) return p2
          if (u.status === 401 || c.status === 401) return fail('请先登录 ChatGPT')
          return fail('ChatGPT 额度接口不可用')
        })
      })
    })
  }

  function parseGeminiHtml(html) {
    if (!html) return null
    var doc = null
    try { doc = new DOMParser().parseFromString(html, 'text/html') } catch (e) { return null }
    var currentPct = null
    var weeklyPct = null
    var currentReset = ''
    function eat(root, weekly) {
      if (!root) return
      var texts = Array.prototype.map.call(root.querySelectorAll('p,div,span'), function (el) { return (el.textContent || '').trim() })
      for (var i = 0; i < texts.length; i++) {
        var t = texts[i]
        var m = t.match(/(\d+)\s*%/)
        if (m) {
          if (weekly && weeklyPct == null) weeklyPct = parseInt(m[1], 10)
          if (!weekly && currentPct == null) currentPct = parseInt(m[1], 10)
        }
        if (/reset/i.test(t) || t.indexOf('重置') !== -1) {
          if (weekly && !currentReset) {}
          if (!weekly && !currentReset) currentReset = t
        }
      }
    }
    eat(doc.querySelector('[data-test-id="gxu-currently"], .gxu-currently'), false)
    eat(doc.querySelector('[data-test-id="gxu-weekly"], .gxu-weekly'), true)
    if (currentPct == null) {
      var all = Array.prototype.map.call(doc.querySelectorAll('p,div,span,h1,h2,h3'), function (el) { return (el.textContent || '').trim() })
      for (var j = 0; j < all.length; j++) {
        var m2 = all[j].match(/(\d+)\s*%\s*(used|已用)?/i)
        if (!m2) continue
        var val = parseInt(m2[1], 10)
        var around = all[j].toLowerCase() + (all[j + 1] || '') + (all[Math.max(0, j - 1)] || '')
        if (/week|weekly|周/.test(around)) {
          if (weeklyPct == null) weeklyPct = val
        } else if (currentPct == null) currentPct = val
      }
    }
    if (currentPct == null && weeklyPct == null) return null
    var used = currentPct != null ? currentPct : weeklyPct
    var remain = clamp(100 - used, 0, 100)
    var hint = currentReset ? currentReset.slice(0, 14) : (weeklyPct != null ? '周已用 ' + weeklyPct + '%' : '今日额度')
    return snapshot(remain, '%', remain, hint)
  }

  function fetchGoogle() {
    return gmRequest({ url: 'https://gemini.google.com/usage?t=' + Date.now() }).then(function (res) {
      if (res.status === 401 || res.status === 403) return fail('请先登录 Gemini')
      var parsed = parseGeminiHtml(res.text)
      if (parsed) return parsed
      if (/Sign in|登录|accounts\.google/i.test(res.text || '')) return fail('请先登录 Gemini')
      return fail('没读到 Gemini 用量页')
    })
  }

  var fetchers = { cursor: fetchCursor, chatgpt: fetchChatGPT, google: fetchGoogle }

  function fmtAmount(snap) {
    if (!snap || !snap.ok) return '--'
    if (snap.broke) return '穷光蛋'
    if (snap.amount === Infinity) return '∞'
    var n = Number(snap.amount)
    if (!isFinite(n)) return '--'
    if (snap.unit === 'USD') return '$' + n.toFixed(2)
    if (snap.unit === '%') return Math.round(n) + '%'
    if (snap.unit === '次' || snap.unit === '条') return String(Math.round(n)) + snap.unit
    return (Math.abs(n) >= 100 ? String(Math.round(n)) : n.toFixed(2)) + (snap.unit ? ' ' + snap.unit : '')
  }

  function mount(initialProvider) {
    injectCss()
    var host = document.body || document.documentElement
    var root = document.createElement('div')
    root.className = 'abw-root'

    var body = document.createElement('div')
    body.className = 'abw-body'

    var img = document.createElement('img')
    img.className = 'abw-img'
    img.src = whaleSrc()
    img.alt = '余额'
    img.draggable = false

    var sizeBox = document.createElement('div')
    sizeBox.className = 'abw-size'
    function makeBtn(text, title, onClick) {
      var b = document.createElement('button')
      b.type = 'button'
      b.textContent = text
      b.title = title
      b.addEventListener('pointerdown', function (e) { e.stopPropagation() })
      b.addEventListener('click', function (e) { e.stopPropagation(); onClick() })
      return b
    }

    var tabs = document.createElement('div')
    tabs.className = 'abw-tabs'
    var tabBtns = {}
    ;['cursor', 'chatgpt', 'google'].forEach(function (id) {
      var b = makeBtn(PROVIDERS[id].short, PROVIDERS[id].label, function () { switchProvider(id) })
      tabBtns[id] = b
      tabs.appendChild(b)
    })

    var textBox = document.createElement('div')
    textBox.className = 'abw-text'
    var labelEl = document.createElement('div')
    labelEl.className = 'abw-label'
    var amountEl = document.createElement('div')
    amountEl.className = 'abw-amount'
    var hintEl = document.createElement('div')
    hintEl.className = 'abw-hint'
    textBox.appendChild(labelEl)
    textBox.appendChild(amountEl)
    textBox.appendChild(hintEl)

    body.appendChild(img)
    body.appendChild(sizeBox)
    body.appendChild(tabs)
    body.appendChild(textBox)
    root.appendChild(body)
    host.appendChild(root)

    var state = {
      scale: 1,
      h: 'right',
      hOff: 0,
      v: 'bottom',
      vOff: 0,
      left: 0,
      top: 0,
      provider: initialProvider,
      snap: null,
      status: 'loading',
      message: ''
    }
    var busy = false
    var settleTimer = null
    var drag = null
    var shownNum = null
    var animId = null

    function express() {
      root.style.right = 'auto'
      root.style.bottom = 'auto'
      root.style.left = state.left + 'px'
      root.style.top = state.top + 'px'
      root.classList.toggle('abw-left', state.h === 'left')
    }
    function settle() {
      var vp = viewport()
      var w = root.offsetWidth || root.getBoundingClientRect().width || 0
      var h = root.offsetHeight || root.getBoundingClientRect().height || 0
      if (drag && drag.active) {
        state.left = clamp(state.left, 0, Math.max(0, vp.w - w))
        state.top = clamp(state.top, 0, Math.max(0, vp.h - h))
        express()
        return
      }
      if (state.h === 'right') state.left = Math.max(0, vp.w - w - state.hOff)
      else if (state.h === 'left') state.left = state.hOff
      else state.left = clamp(state.left, 0, Math.max(0, vp.w - w))
      if (state.v === 'bottom') state.top = Math.max(0, vp.h - h - state.vOff)
      else if (state.v === 'top') state.top = state.vOff
      else state.top = clamp(state.top, 0, Math.max(0, vp.h - h))
      express()
    }

    function paintTabs() {
      Object.keys(tabBtns).forEach(function (id) {
        tabBtns[id].classList.toggle('abw-on', id === state.provider)
      })
    }

    function render() {
      var p = PROVIDERS[state.provider]
      labelEl.textContent = p.label
      var amount = '…'
      var hint = '加载中…'
      amountEl.classList.remove('abw-broke')
      if (state.status === 'error') {
        amount = state.snap && state.snap.ok ? fmtAmount(state.snap) : '--'
        hint = (state.message || '获取失败').slice(0, 14)
      } else if (state.snap && state.snap.ok) {
        amount = fmtAmount(state.snap)
        if (state.snap.broke) amountEl.classList.add('abw-broke')
        hint = state.status === 'changing' ? '加载中…' : (state.snap.hint || '点击刷新')
      } else if (state.status === 'loading') {
        amount = shownNum != null ? String(shownNum) : '…'
        hint = '加载中…'
      }
      amountEl.textContent = amount
      hintEl.textContent = hint
      paintTabs()
    }

    function animateAmount(from, to, snap, duration) {
      if (animId) cancelAnimationFrame(animId)
      if (snap.broke || snap.amount === Infinity || snap.unit === '%') {
        shownNum = to
        render()
        return
      }
      if (from == null || !isFinite(from) || from === to) {
        shownNum = to
        render()
        return
      }
      var startTime = null
      var unit = snap.unit
      function step(ts) {
        if (startTime == null) startTime = ts
        var t = Math.min(1, (ts - startTime) / duration)
        var eased = 1 - Math.pow(1 - t, 3)
        var val = from + (to - from) * eased
        amountEl.classList.remove('abw-broke')
        amountEl.textContent = fmtAmount({ ok: true, amount: val, unit: unit, broke: false })
        if (t < 1) animId = requestAnimationFrame(step)
        else {
          animId = null
          shownNum = to
          render()
        }
      }
      animId = requestAnimationFrame(step)
    }

    function applySnap(snap, manual) {
      if (!snap || !snap.ok) {
        state.status = 'error'
        state.message = (snap && snap.error) ? snap.error : '获取失败'
        render()
        return
      }
      if (snap.remainingPct != null) snap.broke = snap.remainingPct <= BROKE_PCT
      var prev = state.snap && state.snap.ok ? Number(state.snap.amount) : null
      var prevUnit = state.snap && state.snap.unit
      var next = Number(snap.amount)
      var changed = prev != null && isFinite(prev) && isFinite(next) && prev !== next
      state.snap = snap
      state.message = ''
      if (changed && !manual && snap.unit === prevUnit) {
        state.status = 'changing'
        animateAmount(shownNum, next, snap, ANIM_MS)
        if (settleTimer) clearTimeout(settleTimer)
        settleTimer = setTimeout(function () {
          settleTimer = null
          if (state.status === 'changing') { state.status = 'ok'; render() }
        }, CHANGE_MS)
      } else if (changed) {
        animateAmount(shownNum, next, snap, ANIM_MS)
        state.status = 'ok'
        render()
      } else {
        shownNum = next
        state.status = 'ok'
        render()
      }
    }

    function refresh(manual) {
      if (busy) return
      busy = true
      if (manual || !state.snap) { state.status = 'loading'; render() }
      var preview = window.__ABW_PREVIEW__
      var job
      if (preview && preview[state.provider]) job = Promise.resolve(preview[state.provider])
      else job = fetchers[state.provider]()
      job.then(function (snap) { applySnap(snap, manual) })
        .catch(function () { applySnap(fail('获取失败'), manual) })
        .then(function () { busy = false })
    }

    function switchProvider(id) {
      if (!PROVIDERS[id] || id === state.provider) { refresh(true); return }
      state.provider = id
      state.snap = null
      shownNum = null
      gmSet(PROVIDER_KEY, id)
      refresh(true)
    }

    function adjust(delta) {
      var next = Math.round(Math.min(MAX_SCALE, Math.max(MIN_SCALE, state.scale + delta)) * 10) / 10
      state.scale = next
      root.style.setProperty('--abw-scale', String(next))
      gmSet(SIZE_KEY, next)
      settle()
    }

    sizeBox.appendChild(makeBtn('-', '缩小', function () { adjust(-STEP) }))
    sizeBox.appendChild(makeBtn('+', '放大', function () { adjust(STEP) }))

    var SQUISH = 'scaleY(0.88) scaleX(1.05)'
    function onPointerDown(e) {
      if (e.button !== 0) return
      try { root.setPointerCapture(e.pointerId) } catch (err) {}
      var vp = viewport()
      var rect = root.getBoundingClientRect()
      drag = { active: true, startX: e.clientX, startY: e.clientY, origLeft: rect.left, origTop: rect.top, w: rect.width, h: rect.height, moved: false, vp: vp }
      root.classList.add('abw-dragging')
      body.style.transform = SQUISH
    }
    function onPointerMove(e) {
      if (!drag || !drag.active) return
      var dx = e.clientX - drag.startX
      var dy = e.clientY - drag.startY
      if (dx * dx + dy * dy >= CLICK_SQ) drag.moved = true
      state.left = clamp(drag.origLeft + dx, 0, Math.max(0, drag.vp.w - drag.w))
      state.top = clamp(drag.origTop + dy, 0, Math.max(0, drag.vp.h - drag.h))
      express()
    }
    function endDrag(e, clickAllowed) {
      if (!drag || !drag.active) return
      drag.active = false
      body.style.transform = 'scaleY(1) scaleX(1)'
      root.classList.remove('abw-dragging')
      try {
        if (root.hasPointerCapture && root.hasPointerCapture(e.pointerId)) root.releasePointerCapture(e.pointerId)
      } catch (err) {}
      if (clickAllowed && !drag.moved) { refresh(true); return }
      var dx = e.clientX - drag.startX
      var dy = e.clientY - drag.startY
      var left = clamp(drag.origLeft + dx, 0, Math.max(0, drag.vp.w - drag.w))
      var top = clamp(drag.origTop + dy, 0, Math.max(0, drag.vp.h - drag.h))
      var centerX = left + drag.w / 2
      var centerY = top + drag.h / 2
      if (centerX < drag.vp.w / 4) { state.h = 'left'; state.hOff = 0 }
      else if (centerX > drag.vp.w * 3 / 4) { state.h = 'right'; state.hOff = 0 }
      else { state.h = null; state.hOff = left }
      if (centerY < drag.vp.h / 4) { state.v = 'top'; state.vOff = 0 }
      else if (centerY > drag.vp.h * 3 / 4) { state.v = 'bottom'; state.vOff = 0 }
      else { state.v = null; state.vOff = top }
      state.left = left
      state.top = top
      settle()
    }

    root.addEventListener('pointerdown', onPointerDown)
    root.addEventListener('pointermove', onPointerMove)
    root.addEventListener('pointerup', function (e) { endDrag(e, true) })
    root.addEventListener('pointercancel', function (e) { endDrag(e, false) })
    window.addEventListener('resize', settle)

    var rect0 = root.getBoundingClientRect()
    state.left = rect0.left
    state.top = rect0.top
    express()
    render()

    gmGet(SIZE_KEY, 1).then(function (scale) {
      if (typeof scale === 'number' && scale >= MIN_SCALE - 0.1 && scale <= MAX_SCALE + 0.1) {
        state.scale = scale
        root.style.setProperty('--abw-scale', String(scale))
        settle()
      }
      refresh(false)
    }).catch(function () { refresh(false) })

    setInterval(function () { refresh(false) }, REFRESH_MS)
  }

  function boot() {
    var start = function () {
      var def = hostOf()
      gmGet(PROVIDER_KEY, def).then(function (saved) {
        mount(PROVIDERS[saved] ? saved : def)
      }).catch(function () { mount(def) })
    }
    if (document.body) start()
    else document.addEventListener('DOMContentLoaded', start)
  }

  boot()
})()
